insert into public.yadigar_facts (place_id, text_tr, text_en, source) values
  (1, 'Yıldırım Darüşşifası''nda cerrahlar, ameliyattan önce hastalardan mahkeme onaylı rıza senedi alırdı.', 'Surgeons at the Yıldırım Darüşşifa took court-approved consent forms from patients before operating.', 'Zaman Aynası veritabanı: hotspot 1'),
  (1, 'Yıldırım Darüşşifası''nda ruh hastaları su sesi ve musikiyle tedavi edilirdi.', 'The Yıldırım Darüşşifa treated mental illness with the sound of water and music.', 'Zaman Aynası veritabanı: hotspot 3'),
  (1, 'Osmanlı''nın ilk hastanesi Yıldırım Darüşşifası, 1855 depreminden sonra barut deposu olarak kullanıldı.', 'The Yıldırım Darüşşifa, the first Ottoman hospital, served as a gunpowder store after the 1855 earthquake.', 'Zaman Aynası veritabanı: hotspot 2'),
  (1, 'Yıldırım Darüşşifası''nda başta 3 tabip, 2 şerbetçi ve 2 eczacı çalışıyordu; zamanla görevli sayısı 27''ye çıktı.', 'The Yıldırım Darüşşifa started with 3 physicians, 2 sherbet makers and 2 pharmacists, and later grew to 27 staff.', 'Bursa Envanteri, Cilt 2, s. 452–453'),
  (2, 'Ördekli Hamamı adını kurnalarının şeklinden alır.', 'The Ördekli Bath takes its name from the shape of its basins.', 'Zaman Aynası veritabanı: audio_text'),
  (2, 'Ördekli Hamamı''nın kubbesinde, ışığı içeri süzen 93 fil gözü cam vardır.', '93 glass ''elephant eyes'' in the dome of the Ördekli Bath let the daylight in.', 'Zaman Aynası veritabanı: short_description, hotspot 4'),
  (2, 'Ördekli Hamamı, büyük kubbesi uzun süre yıkık kaldığı için ''Yıkık Hamam'' diye de anıldı.', 'The Ördekli Bath was also called the ''Ruined Bath'' because its great dome lay in ruins for a long time.', 'Bursa Envanteri, Cilt 2, s. 150–151'),
  (2, 'Ördekli Hamamı''nın inşaatı Timur işgaliyle yarım kalınca, hamam için getirilen su çevredeki evlere yönlendirildi.', 'When Timur''s invasion halted the Ördekli Bath, the water brought for it was diverted to nearby houses.', 'Bursa Envanteri, Cilt 2, s. 150–151'),
  (3, 'Bursa Dullar Evi, 1916''da şehit eşleri ve çocukları için kuruldu.', 'The Bursa Widows'' House was founded in 1916 for the widows and children of fallen soldiers.', 'Zaman Aynası veritabanı: short_description'),
  (3, 'Bursa Dullar Evi''nin altındaki fırının kirası, orada kalan okur-yazar bir şehit eşine müdire maaşı olarak ödenirdi.', 'The rent from the bakery below the Bursa Widows'' House paid a literate widow living there as its director.', 'Zaman Aynası veritabanı: audio_text'),
  (3, 'Bursa Dullar Evi''nin yönetimi Bursa Belediye Başkanı ile il müftüsüne verilmişti.', 'The Bursa Widows'' House was run jointly by the mayor of Bursa and the city mufti.', 'Bursa Envanteri, Cilt 2, s. 110–111'),
  (4, 'Karabaş-ı Velî Dergâhı adını Şeyh Yakub Çelebi''nin siyah sarığından alır.', 'The Karabaş-ı Velî Lodge is named after Sheikh Yakub Çelebi''s black turban.', 'Zaman Aynası veritabanı: audio_text'),
  (4, 'Karabaş-ı Velî Dergâhı''nın semahanesi, 1925''ten sonra bir süre gençlerin antrenman yaptığı bir spor kulübü oldu.', 'After 1925 the Karabaş-ı Velî Lodge''s sema hall was used for a while as a sports club for young people.', 'Zaman Aynası veritabanı: hotspot 9'),
  (4, 'Karabaş-ı Velî Dergâhı, tapu kayıtlarında ''Pir Ali Çelebi Dergâhı'' olarak geçer.', 'The Karabaş-ı Velî Lodge appears in the land registry as the ''Pir Ali Çelebi Lodge''.', 'Bursa Envanteri, Cilt 2, s. 162–163'),
  (5, 'Koza Hanı''nın avlusundaki köşk mescidin altında, tüccarların abdest alıp serinlediği bir şadırvan vardır.', 'Beneath the small mosque in the Koza Han courtyard there is a fountain where merchants washed and cooled off.', 'Zaman Aynası veritabanı: hotspot 13'),
  (5, 'Koza Hanı''nda İtalya''dan ve İran''dan gelen tüccarlar ipek pazarlığı yapardı.', 'Merchants from Italy and Iran bargained for silk inside the Koza Han.', 'Zaman Aynası veritabanı: audio_text'),
  (5, 'Koza Hanı, ''Hân-ı Cedîd-i Evvel'', yani ''Birinci Yeni Han'' adıyla da anılırdı.', 'The Koza Han was also known as ''Hân-ı Cedîd-i Evvel'', the ''First New Han''.', 'Bursa Envanteri, Cilt 2, s. 42–43'),
  (5, 'Koza Hanı''nın ahır bölümü için 1490''da dört ev 21.600 akçeye istimlak edildi.', 'Four houses were expropriated for 21,600 silver coins in 1490 to build the Koza Han''s stables.', 'Bursa Envanteri, Cilt 2, s. 40–41'),
  (6, 'Pirinç Hanı''nın zemin katında pirinç ve tahıl saklanır, üst katında yabancı tüccarlar konaklardı.', 'The Pirinç Han stored rice and grain on its ground floor while foreign merchants stayed upstairs.', 'Zaman Aynası veritabanı: audio_text, hotspot 92'),
  (6, 'Pirinç Hanı, Koza Hanı''ndan sonra yapılan ikinci büyük han olduğu için ''İkinci Yeni Han'' diye anıldı.', 'The Pirinç Han, the second great han built after the Koza Han, was called the ''Second New Han''.', 'Bursa Envanteri, Cilt 2, s. 42–43'),
  (6, 'Pirinç Hanı''nın inşaatı Mayıs 1507''de başladı, Temmuz 1508''de bitti.', 'The Pirinç Han was built between May 1507 and July 1508.', 'Bursa Envanteri, Cilt 2, s. 42–43'),
  (7, 'Mimar Hacı İvaz Paşa, Geyve Hanı''nı kendi servetiyle yaptırıp Yeşil Külliyesi''ne bağışladı.', 'The architect Hacı İvaz Paşa built the Geyve Han with his own money and donated it to the Green Complex.', 'Zaman Aynası veritabanı: audio_text'),
  (7, 'Geyve Hanı''nın mescidi avluda değil, üst kattaki kubbeli bir odadadır.', 'The Geyve Han''s prayer room is not in the courtyard but in a domed room on the upper floor.', 'Zaman Aynası veritabanı: hotspot 96'),
  (7, 'Geyve Hanı, yaptıran Hacı İvaz Paşa bir ahi olduğu için ilk yıllarda ''Lonca Hanı'' diye anıldı.', 'The Geyve Han was first called the ''Guild Han'' because its builder Hacı İvaz Paşa was a guild member.', 'Bursa Envanteri, Cilt 2, s. 30–31'),
  (8, 'Aynalı Çarşı aslında Orhan Gazi''nin 1340''ta yaptırdığı bir hamamdır.', 'The Aynalı Çarşı was originally a bathhouse built by Orhan Gazi in 1340.', 'Zaman Aynası veritabanı: short_description'),
  (8, 'Aynalı Çarşı adı, 1960''larda çarşıya dönüşen hamamda esnafın astığı aynalardan gelir.', 'The Aynalı (Mirrored) Bazaar is named after the mirrors shopkeepers hung when the bath became a market in the 1960s.', 'Zaman Aynası veritabanı: audio_text'),
  (9, 'Ulu Camii''nin minberi hiç çivi ve tutkal kullanılmadan 6.666 ahşap parçayla yapıldı.', 'The pulpit of the Grand Mosque was made from 6,666 wooden pieces without a single nail or glue.', 'Zaman Aynası veritabanı: hotspot 20'),
  (9, 'Ulu Camii''nin minberinde Güneş sistemi ve galaksi yörüngeleri tasvir edilir.', 'The pulpit of the Grand Mosque depicts the orbits of the solar system and the galaxy.', 'Zaman Aynası veritabanı: hotspot 20'),
  (9, 'Ulu Camii, 20 kubbesiyle Niğbolu Zaferi''nin şükranı olarak yaptırıldı.', 'The Grand Mosque, with its 20 domes, was built in thanks for the victory at Nicopolis.', 'Zaman Aynası veritabanı: short_description'),
  (9, 'Ulu Camii''nin müezzin mahfilinin altındaki 1549 tarihli kitabe, camide tarihi bilinen en eski yazıdır.', 'The 1549 inscription under the muezzin''s gallery is the oldest dated writing in the Grand Mosque.', 'Zaman Aynası veritabanı: hotspot 21'),
  (10, 'Yeşil Camii''nin mermer taç kapısı üç yılda işlendi.', 'The marble portal of the Green Mosque took three years to carve.', 'Zaman Aynası veritabanı: hotspot 25'),
  (10, 'Yeşil Camii''ndeki hünkâr mahfili, Osmanlı''daki ilk hünkâr mahfilidir.', 'The sultan''s lodge in the Green Mosque was the first of its kind in the Ottoman world.', 'Zaman Aynası veritabanı: hotspot 28'),
  (10, 'Yeşil Camii''nin ortasındaki fıskiyeli havuz, gizli devlet görüşmelerinin sesini örterdi.', 'The fountain pool at the centre of the Green Mosque masked the sound of secret state talks.', 'Zaman Aynası veritabanı: hotspot 32'),
  (11, 'Yeşil Türbe, dış cephesi tamamen çinilerle kaplı tek anıt mezardır.', 'The Green Tomb is the only monumental tomb whose exterior is entirely covered in tiles.', 'Zaman Aynası veritabanı: short_description'),
  (11, 'Yeşil Türbe''deki Çelebi Mehmed''in çinili sandukası 2,77 metre uzunluğundadır.', 'Mehmed I''s tiled sarcophagus in the Green Tomb is 2.77 metres long.', 'Zaman Aynası veritabanı: hotspot 39'),
  (11, 'Yeşil Türbe 25,5 metre yüksekliğindedir.', 'The Green Tomb rises 25.5 metres high.', 'Zaman Aynası veritabanı: short_description'),
  (11, 'Çelebi Mehmed''in süt annesi Dâye Hatun, Yeşil Türbe''de onun ayak ucunda yatar.', 'Mehmed I''s wet nurse, Dâye Hatun, is buried at his feet in the Green Tomb.', 'Bursa Envanteri, Cilt 1, s. 300–301'),
  (12, 'Hüdavendigâr Camii, alt katı cami üst katı medrese olan dünyadaki tek iki katlı yapıdır.', 'The Hüdavendigâr Mosque is the world''s only two-storey building with a mosque below and a madrasa above.', 'Zaman Aynası veritabanı: short_description'),
  (12, 'Hüdavendigâr Camii''nin cephesinde kuşlar için taş ve tuğladan yapılmış kuş evleri vardır.', 'The façade of the Hüdavendigâr Mosque has stone and brick birdhouses built for birds to nest in.', 'Zaman Aynası veritabanı: hotspot 106'),
  (12, 'Hüdavendigâr Camii''ne Çekirge''nin kaplıcaları yüzünden ''Kaplıca İmareti'' de denirdi.', 'The Hüdavendigâr complex was also called the ''Hot Spring Imaret'' because of Çekirge''s thermal springs.', 'Bursa Envanteri, Cilt 1, s. 82–83'),
  (13, 'Irgandı Köprüsü''nün kemer ayaklarının içinde, tüccarların mallarını sakladığı depolar vardır.', 'The piers of the Irgandı Bridge hide storerooms where merchants kept their goods.', 'Zaman Aynası veritabanı: hotspot 49'),
  (13, 'Irgandı Köprüsü 1922''de bombalandı, 2004''te yeniden zanaat çarşısı olarak onarıldı.', 'The Irgandı Bridge was bombed in 1922 and restored as a crafts bazaar in 2004.', 'Zaman Aynası veritabanı: hotspot 47'),
  (13, 'Irgandı Köprüsü, Türkiye''deki tek çarşılı köprüdür ve Floransa''daki Ponte Vecchio''ya benzetilir.', 'The Irgandı Bridge is the only bridge in Turkey with a bazaar on it, often compared to Florence''s Ponte Vecchio.', 'Bursa Envanteri, Cilt 2, s. 558–559'),
  (14, 'Muradiye Külliyesi''nin bahçesinde 13 hanedan türbesi bulunur.', 'The gardens of the Muradiye Complex hold 13 dynastic tombs.', 'Zaman Aynası veritabanı: short_description'),
  (14, 'Muradiye Külliyesi, Bursa''daki son selatin külliyesidir.', 'The Muradiye is the last imperial complex built in Bursa.', 'Zaman Aynası veritabanı: short_description'),
  (14, 'Muradiye Külliyesi''ndeki ''Üç Hanım Kızlar Türbesi''nde aslında dört saraylı kadının yattığı arşivlerden anlaşıldı.', 'Archives revealed four palace women, not three, are buried in the Muradiye''s ''Three Ladies Tomb''.', 'Bursa Envanteri, Cilt 2, s. 216–217'),
  (15, 'Emir Sultan Külliyesi''ni Yıldırım Bayezid''in kızı Hundi Hatun, eşi Emir Sultan adına yaptırdı.', 'The Emir Sultan Complex was built by Bayezid I''s daughter Hundi Hatun in the name of her husband Emir Sultan.', 'Zaman Aynası veritabanı: short_description'),
  (15, 'Emir Sultan Külliyesi''ndeki niyaz penceresi, yüzyıllardır dua etmek isteyen ziyaretçilerin uğrak yeridir.', 'The prayer window of the Emir Sultan Complex has drawn visitors for centuries.', 'Zaman Aynası veritabanı: hotspot 57'),
  (15, 'Emir Sultan Külliyesi''nde cami ve türbenin yanında bir muvakkithane, yani vakit hesaplanan bir saat odası da vardı.', 'The Emir Sultan Complex once included a timekeeper''s room alongside its mosque and tomb.', 'Bursa Envanteri, Cilt 2, s. 272–273'),
  (16, 'Yeşil Külliye, çok renkli sır altı çini tekniğinin ilk kez toplu olarak uygulandığı yerdir.', 'The Green Complex was the first place where multicoloured underglaze tiles were used on a large scale.', 'Zaman Aynası veritabanı: short_description'),
  (16, 'Yeşil Külliye cami, türbe, medrese, imaret ve hamamdan oluşur.', 'The Green Complex is made up of a mosque, a tomb, a madrasa, a soup kitchen and a bath.', 'Zaman Aynası veritabanı: short_description'),
  (17, 'Muradiye Camii''nin yanlarındaki tabhane odalarında yolcular konaklardı.', 'Travellers could stay in the side rooms of the Muradiye Mosque.', 'Zaman Aynası veritabanı: hotspot 65'),
  (17, 'Muradiye Camii''nin duvarları, taş ve tuğlanın sırayla dizildiği almaşık örgüyle yapıldı.', 'The walls of the Muradiye Mosque alternate courses of stone and brick.', 'Zaman Aynası veritabanı: short_description'),
  (18, 'Muradiye Medresesi bugün El Yazmaları Müzesi olarak hizmet veriyor.', 'The Muradiye Madrasa is now a manuscripts museum.', 'Zaman Aynası veritabanı: short_description'),
  (18, 'Muradiye Medresesi''nde avluyu çevreleyen 16 kubbeli talebe hücresi vardır.', '16 domed student cells surround the courtyard of the Muradiye Madrasa.', 'Zaman Aynası veritabanı: hotspot 69'),
  (19, 'Sultan II. Murad Türbesi''nin kubbesi, sultanın ''yağmur rahmeti üzerime yağsın'' vasiyetiyle ortası açık bırakıldı.', 'The dome of Murad II''s tomb was left open in the middle because he asked for the rain to fall on his grave.', 'Zaman Aynası veritabanı: hotspot 73'),
  (19, 'Sultan II. Murad, sandukası olmadan doğrudan toprağa gömüldü.', 'Sultan Murad II was buried directly in the earth, without a sarcophagus.', 'Zaman Aynası veritabanı: hotspot 73'),
  (20, 'Cem Sultan Türbesi aslında 1479''da Şehzade Mustafa için yapıldı.', 'The tomb of Cem Sultan was originally built in 1479 for Prince Mustafa.', 'Zaman Aynası veritabanı: short_description'),
  (20, 'Cem Sultan Türbesi''nin iç duvarları 2,35 metreye kadar firuze ve lacivert çinilerle kaplıdır.', 'The inner walls of Cem Sultan''s tomb are covered in turquoise and navy tiles up to 2.35 metres.', 'Zaman Aynası veritabanı: hotspot 75'),
  (20, 'Cem Sultan Türbesi''nde Cem Sultan dahil dört şehzade yatar.', 'Four princes, including Cem Sultan, are buried in the Cem Sultan Tomb.', 'Bursa Envanteri, Cilt 1, s. 144–145'),
  (20, 'Cem Sultan Napoli''de vefat etti; cenazesi 1499''da Bursa''ya getirildi.', 'Cem Sultan died in Naples and his body was brought to Bursa in 1499.', 'Bursa Envanteri, Cilt 1, s. 144–145'),
  (21, 'Şirin Hatun Türbesi''ni Sultan II. Bayezid''in eşi Şirin Hatun yaptırdı.', 'The Şirin Hatun Tomb was commissioned by Şirin Hatun, wife of Sultan Bayezid II.', 'Zaman Aynası veritabanı: short_description'),
  (21, 'Şirin Hatun Türbesi''nin duvarları bir sıra küfeki taşı ve iki sıra tuğlayla örüldü.', 'The walls of the Şirin Hatun Tomb alternate one course of küfeki stone with two of brick.', 'Zaman Aynası veritabanı: hotspot 79'),
  (21, 'Şirin Hatun, türbesini daha hayattayken yaptırdı.', 'Şirin Hatun had her tomb built while she was still alive.', 'Bursa Envanteri, Cilt 1, s. 170–171'),
  (23, 'Yeşil Medrese bugün Türk İslam Eserleri Müzesi''dir.', 'The Green Madrasa is now the Museum of Turkish and Islamic Arts.', 'Zaman Aynası veritabanı: short_description'),
  (23, 'Yeşil Medrese''nin bahçesinde Bursa''nın tarihi yapılarından kurtarılan mezar taşları sergilenir.', 'The Green Madrasa''s garden displays gravestones rescued from Bursa''s historic buildings.', 'Zaman Aynası veritabanı: hotspot 86');
